const PLUGIN_FILES = {"confetti.js":"/*  Confetti: a built-in SungFluence style.\n    Letters are packed from large to small. Calm areas get large letters, detailed areas (eyes, a mouth, whiskers)\n    get small ones, so a face stays a face. Letters can turn along the lines of the picture.\n    MIT licensed, like the plugin template, so plugin authors can borrow from it.\n*/\nSungfluence.plugin({\n  api: 1,\n  id: 'confetti',\n  name: 'Confetti',\n  icon: 'a*b',\n  version: '2.0.0',\n  author: 'SungFluence',\n  description: 'Packed letters: large in calm areas, small in the details, turned along the picture.',\n  inkDriven: true,\n  defaults: { text: 'confetti', density: 1, maxSize: 44, minSize: 8, detail: 0.7, turn: 'flow', spin: 0.3, overlap: 0.15, power: 1, weightMod: true, color: 'image', colorLift: 0.35, font: 'sans', weight: 700, upper: false, sep: '' },\n  controls: [\n    { key: 'text', label: 'Letters to scatter', type: 'textarea' },\n    { key: 'density', label: 'Density', type: 'range', min: 0.3, max: 2, step: 0.05 },\n    { key: 'maxSize', label: 'Largest letter', type: 'range', min: 8, max: 120, step: 1 },\n    { key: 'minSize', label: 'Smallest letter', type: 'range', min: 2, max: 30, step: 0.5 },\n    { key: 'detail', label: 'Small letters in the details', type: 'range', min: 0, max: 1, step: 0.05 },\n    { key: 'turn', label: 'Letters turn', type: 'choice', options: [['flow', 'Along the picture'], ['random', 'At random'], ['upright', 'Upright']] },\n    { type: 'color', options: ['image', 'ink', 'tone', 'duotone'] },\n    { type: 'font' },\n    { key: 'spin', label: 'Extra spin', type: 'range', min: 0, max: 1, step: 0.05, more: true },\n    { key: 'overlap', label: 'Overlap', type: 'range', min: 0, max: 0.9, step: 0.05, more: true },\n    { key: 'power', label: 'Leave light areas emptier', type: 'range', min: 0.3, max: 3, step: 0.1, more: true },\n    { key: 'weightMod', label: 'Bolder letters in dark areas', type: 'toggle', more: true },\n    { key: 'upper', label: 'Capitals', type: 'toggle', more: true }\n  ],\n\n  *render(api) {\n    const p = api.params, W = api.W, H = api.H, R = api.random;\n    const G = api.grid;\n    const minS = Math.max(1.5, Math.min(p.minSize, p.maxSize)), maxS = Math.max(minS, p.maxSize);\n\n    // 1. detail: how much the tone changes nearby. High in eyes and edges, low in flat fur or sky.\n    // It is measured on a small copy of the tones (at most 400 across): detail at letter scale needs no more.\n    const f = Math.max(1, Math.ceil(G.w / 400)), gw = Math.ceil(G.w / f), gh = Math.ceil(G.h / f), n = gw * gh;\n    const small = new Float32Array(n);\n    for (let y = 0; y < gh; y++) {\n      if ((y & 63) === 0) yield 0.02 * y / gh;\n      for (let x = 0; x < gw; x++) {\n        let s = 0, c = 0;\n        for (let yy = y * f; yy < Math.min(G.h, y * f + f); yy++) for (let xx = x * f; xx < Math.min(G.w, x * f + f); xx++) { s += G.ink[yy * G.w + xx]; c++; }\n        small[y * gw + x] = s / c;\n      }\n    }\n    // measured at the scale of a letter, so fur and grain do not count as detail\n    const r1 = Math.max(1, Math.round(gw / 110)), r2 = Math.max(2, Math.round(gw / 28));\n    const fine = api.blur(small, gw, gh, r1);\n    yield 0.04;\n    const coarse = api.blur(small, gw, gh, r2);\n    yield 0.08;\n    let det = new Float32Array(n);\n    for (let i = 0; i < n; i++) det[i] = Math.abs(fine[i] - coarse[i]);\n    det = api.blur(det, gw, gh, Math.max(1, Math.round(gw / 60)));\n    yield 0.12;\n    // the 98.5th percentile from a histogram: sorting a full-size picture would freeze the window\n    let top = 1e-6;\n    for (let i = 0; i < n; i++) if (det[i] > top) top = det[i];\n    const hist = new Uint32Array(512);\n    for (let i = 0; i < n; i++) hist[Math.min(511, Math.floor(det[i] / top * 511))]++;\n    let acc = 0, bin = 511;\n    for (let k = 0; k < 512; k++) { acc += hist[k]; if (acc >= n * 0.985) { bin = k; break; } }\n    const hi = Math.max(1e-3, (bin + 1) / 512 * top);\n    for (let i = 0; i < n; i++) det[i] = Math.min(1, det[i] / hi);\n    yield 0.16;\n    const gi = (x, y) => Math.min(gh - 1, Math.max(0, Math.floor(y / H * gh))) * gw + Math.min(gw - 1, Math.max(0, Math.floor(x / W * gw)));\n    // direction along the edges, from the smoothed tones\n    const flowAt = (x, y) => {\n      const X = Math.min(gw - 2, Math.max(1, Math.floor(x / W * gw))), Y = Math.min(gh - 2, Math.max(1, Math.floor(y / H * gh)));\n      const i = Y * gw + X;\n      const dx = coarse[i + 1] - coarse[i - 1], dy = coarse[i + gw] - coarse[i - gw];\n      if (Math.abs(dx) + Math.abs(dy) < 1e-4) return 0;\n      let a = Math.atan2(dy, dx) + Math.PI / 2;\n      // keep letters readable: never upside down\n      while (a > Math.PI / 2) a -= Math.PI;\n      while (a < -Math.PI / 2) a += Math.PI;\n      return a;\n    };\n\n    // 2. occupancy grid: a placed letter claims a round spot, so letters do not pile up\n    const cell = Math.max(1, minS * 0.5), cw = Math.ceil(W / cell), ch = Math.ceil(H / cell);\n    const used = new Uint8Array(cw * ch);\n    const free = (x, y, rad) => {\n      const c0 = Math.floor((x - rad) / cell), c1 = Math.floor((x + rad) / cell), r0 = Math.floor((y - rad) / cell), r1c = Math.floor((y + rad) / cell);\n      for (let r = Math.max(0, r0); r <= Math.min(ch - 1, r1c); r++) for (let c = Math.max(0, c0); c <= Math.min(cw - 1, c1); c++) {\n        const cx = (c + 0.5) * cell - x, cy = (r + 0.5) * cell - y;\n        if (cx * cx + cy * cy <= rad * rad && used[r * cw + c]) return false;\n      }\n      return true;\n    };\n    const claim = (x, y, rad) => {\n      const c0 = Math.floor((x - rad) / cell), c1 = Math.floor((x + rad) / cell), r0 = Math.floor((y - rad) / cell), r1c = Math.floor((y + rad) / cell);\n      for (let r = Math.max(0, r0); r <= Math.min(ch - 1, r1c); r++) for (let c = Math.max(0, c0); c <= Math.min(cw - 1, c1); c++) {\n        const cx = (c + 0.5) * cell - x, cy = (r + 0.5) * cell - y;\n        if (cx * cx + cy * cy <= rad * rad) used[r * cw + c] = 1;\n      }\n    };\n\n    // 3. sizes from large to small. A size is allowed where the detail is low enough for it.\n    const levels = Math.max(2, Math.min(9, Math.round(Math.log(maxS / minS) / Math.log(1.45)) + 1));\n    const letters = api.text({ sep: p.sep ?? '' });\n    const nextLetter = () => { for (let k = 0; k < 6; k++) { const c = letters.next(); if (c !== ' ') return c; } return null; };\n    const keep = 1 - (p.overlap ?? 0.2);\n    const dens = p.density ?? 1, dw = p.detail ?? 0.8, pow = p.power ?? 1;\n    let done = 0;\n    for (let L = 0; L < levels; L++) {\n      const t = levels === 1 ? 1 : L / (levels - 1);\n      const s = maxS * Math.pow(minS / maxS, t);\n      const step = Math.max(1, s * 0.85 / dens);\n      const last = L === levels - 1;\n      for (let y = step / 2; y < H; y += step) {\n        if ((++done & 7) === 0) yield 0.18 + 0.8 * (L + y / H) / levels;\n        for (let x = step / 2; x < W; x += step) {\n          const px = x + (R() - 0.5) * step, py = y + (R() - 0.5) * step;\n          if (px < 0 || py < 0 || px >= W || py >= H) continue;\n          const ink = api.ink(px, py);\n          // a letter covers only part of its spot, so mid tones need most spots filled\n          if (ink < 0.04 || R() > Math.pow(Math.min(1, ink * 1.6), pow)) continue;\n          // the largest letter this spot can take: detailed spots take only small letters\n          const d = det[gi(px, py)];\n          const fit = maxS * Math.pow(minS / maxS, Math.min(1, Math.pow(d, 1.3) * dw * 1.8));\n          if (s > fit * 1.2 && !last) continue;\n          // dark areas pack tighter, so they read darker\n          const rad = s * 0.5 * keep * (1 - 0.35 * ink);\n          if (!free(px, py, rad)) continue;\n          const c = nextLetter();\n          if (!c) continue;\n          claim(px, py, rad);\n          let angle = 0;\n          if (p.turn === 'flow') angle = flowAt(px, py);\n          else if (p.turn === 'random') angle = (R() - 0.5) * Math.PI * 1.4;\n          angle += (R() - 0.5) * Math.PI * (p.spin ?? 0.3);\n          // letters a little smaller in light areas, so tones still read\n          api.addText(c, px, py, { size: s * (0.75 + 0.25 * ink), angle, weight: p.weightMod === false ? undefined : Math.round((400 + 500 * ink) / 100) * 100 });\n        }\n      }\n    }\n  }\n});\n","contour-words.js":"/*  Contour words: a SungFluence plugin\n    Text follows lines of equal tone, like contour lines on a topographic map\n    or depth lines on a river survey. Every Nth line is bolder, as on real maps.\n\n    Method: the picture's tone is sampled on a small grid, smoothed, and cut at\n    evenly spaced levels with marching squares. Line pieces are joined into\n    long contours, and the layer's text is written along them.\n    MIT licensed. */\n\nSungfluence.plugin({\n  api: 1,\n  id: 'contour-words',\n  name: 'Contours',\n  icon: '≈',\n  version: '1.0.0',\n  author: 'SungFluence',\n  description: 'Text along lines of equal tone, like a topographic or river depth map.',\n  stage: 'Drawing contour lines',\n\n  defaults: { text: 'river · flow · depth · current · bank · bed · sediment · channel', levels: 10, size: 11, smooth: 4, detail: 260, index: 5, minLen: 4, color: 'ink', font: 'condensed', weight: 500, upper: true, sep: ' · ', tracking: 0.04 },\n\n  controls: [\n    { key: 'text', label: 'Text along the contours', type: 'textarea' },\n    { key: 'levels', label: 'Contour lines', type: 'range', min: 3, max: 40, step: 1 },\n    { key: 'size', label: 'Letter size', type: 'range', min: 4, max: 40, step: 0.5 },\n    { key: 'smooth', label: 'Smoothness', type: 'range', min: 1, max: 12, step: 1 },\n    { type: 'color', options: ['ink', 'image', 'tone', 'duotone'] },\n    { type: 'font' },\n    { key: 'index', label: 'Bold line', type: 'choice', options: [[0, 'Off'], [4, 'Every 4th'], [5, 'Every 5th']], more: true },\n    { key: 'detail', label: 'Detail', type: 'range', min: 120, max: 480, step: 10, more: true },\n    { key: 'minLen', label: 'Shortest line, in letters', type: 'range', min: 1, max: 20, step: 1, more: true },\n    { key: 'upper', label: 'Capitals', type: 'toggle', more: true }\n  ],\n\n  *render(api) {\n    const p = api.params;\n    // 1. Sample the tone on a fixed grid, so previews and exports draw the same lines.\n    const gw = Math.max(16, Math.round(p.detail));\n    const gh = Math.max(16, Math.round(gw * api.H / api.W));\n    const cw = api.W / gw, ch = api.H / gh;\n    let f = new Float32Array(gw * gh);\n    for (let y = 0; y < gh; y++) {\n      for (let x = 0; x < gw; x++) f[y * gw + x] = api.area(x * cw, y * ch, (x + 1) * cw, (y + 1) * ch).ink;\n      if (y % 40 === 0) yield 0.1 * y / gh;\n    }\n    f = api.blur(f, gw, gh, p.smooth);\n\n    const nLev = Math.max(1, Math.round(p.levels));\n    const plain = [], bold = [];\n    const minPx = p.minLen * p.size * 0.6;\n    // edge ids: horizontal edge (x,y)-(x+1,y) is 2*(y*gw+x); vertical edge (x,y)-(x,y+1) is 2*(y*gw+x)+1\n    const nE = 2 * gw * gh;\n    const ex = new Float32Array(nE), ey = new Float32Array(nE);\n    const a1 = new Int32Array(nE), a2 = new Int32Array(nE), seen = new Uint8Array(nE);\n\n    for (let li = 0; li < nLev; li++) {\n      yield 0.1 + 0.6 * li / nLev;\n      const t = (li + 1) / (nLev + 1);\n      a1.fill(-1); a2.fill(-1); seen.fill(0);\n      const touched = [];\n      const point = (e) => {\n        const c = e >> 1, x = c % gw, y = (c / gw) | 0;\n        const v0 = f[c], v1 = (e & 1) ? f[c + gw] : f[c + 1];\n        const k = Math.min(1, Math.max(0, (t - v0) / ((v1 - v0) || 1e-6)));\n        ex[e] = ((e & 1) ? x : x + k) + 0.5;\n        ey[e] = ((e & 1) ? y + k : y) + 0.5;\n      };\n      const link = (e1, e2) => {\n        for (const [a, b] of [[e1, e2], [e2, e1]]) {\n          if (a1[a] < 0 && a2[a] < 0) { touched.push(a); point(a); }\n          if (a1[a] < 0) a1[a] = b; else a2[a] = b;\n        }\n      };\n      for (let y = 0; y < gh - 1; y++) {\n        for (let x = 0; x < gw - 1; x++) {\n          const i = y * gw + x;\n          const code = (f[i] > t ? 8 : 0) | (f[i + 1] > t ? 4 : 0) | (f[i + gw + 1] > t ? 2 : 0) | (f[i + gw] > t ? 1 : 0);\n          if (code === 0 || code === 15) continue;\n          const top = 2 * i, bottom = 2 * (i + gw), left = 2 * i + 1, right = 2 * (i + 1) + 1;\n          switch (code) {\n            case 1: case 14: link(left, bottom); break;\n            case 2: case 13: link(bottom, right); break;\n            case 3: case 12: link(left, right); break;\n            case 4: case 11: link(top, right); break;\n            case 6: case 9: link(top, bottom); break;\n            case 7: case 8: link(left, top); break;\n            case 5: link(left, top); link(bottom, right); break;\n            case 10: link(top, right); link(left, bottom); break;\n          }\n        }\n      }\n      // 2. Join the pieces into long lines. Open lines first, then closed loops.\n      const isIndex = p.index > 0 && (li + 1) % p.index === 0;\n      const walk = (start) => {\n        const pts = [];\n        let prev = -1, cur = start;\n        while (cur >= 0 && !seen[cur]) {\n          seen[cur] = 1;\n          pts.push([ex[cur] * cw, ey[cur] * ch]);\n          const n = a1[cur] !== prev ? a1[cur] : a2[cur];\n          prev = cur; cur = n;\n        }\n        if (cur === start && pts.length > 2) pts.push(pts[0].slice());\n        let len = 0;\n        for (let k = 1; k < pts.length; k++) len += Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]);\n        if (len >= minPx) (isIndex ? bold : plain).push(pts);\n      };\n      for (const e of touched) if (!seen[e] && (a1[e] < 0 || a2[e] < 0)) walk(e);\n      for (const e of touched) if (!seen[e]) walk(e);\n    }\n\n    // 3. Write the text along the contours. Bold lines get heavier, slightly larger letters.\n    const write = function* (paths, o, from, to) {\n      if (!paths.length) return;\n      const g = api.writeAlong(paths, o);\n      let s;\n      while (!(s = g.next()).done) yield from + (to - from) * (s.value || 0);\n    };\n    yield* write(plain, { size: p.size }, 0.7, 0.9);\n    yield* write(bold, { size: p.size * 1.15, weight: Math.min(900, (p.weight || 500) + 300) }, 0.9, 1);\n  }\n});\n","sungfluence-plugin-template.js":"/*  SungFluence plugin template\n    ========================\n    A plugin adds one new style to the Text art panel.\n\n    How to make your own:\n      1. Copy this file and give it a new name, for example my-style.js\n      2. Change id, name and icon below. The id must be unique.\n      3. Edit render(). Keep the rest as it is.\n      4. In SungFluence click Plugins at the top (or Plugins in the menu bar), then Load plugin, and pick your file.\n      5. Your style now shows up under Style, in Extra effects. Change a setting and it redraws.\n\n    Plugins run code inside SungFluence. Only load plugins you trust.\n    This template is MIT licensed. Use it for anything.\n\n    ---------------------------------------------------------------\n    What render(api) gets\n    ---------------------------------------------------------------\n    api.W, api.H            artboard size in pixels. (0, 0) is the top left corner.\n    api.params              the current settings of this layer (your defaults plus what the user changed).\n                            Settings named size, spacing, minSize and maxSize are already scaled\n                            for fast previews, so the preview looks like the final export.\n    api.scale               preview scale (1 at export). Multiply your own pixel sizes by it.\n    api.random()            a seeded random number from 0 to 1. Same seed, same picture.\n\n    Reading the picture (x, y in artboard pixels):\n    api.ink(x, y)           0 = empty paper, 1 = the darkest part. On dark paper the light parts get the ink.\n    api.rgb(x, y)           [r, g, b], each 0 to 1\n    api.hex(x, y)           '#rrggbb'\n    api.kept(x, y)          false where the user removed the background\n    api.area(x0, y0, x1, y1)  average {ink, r, g, b} over a rectangle. Fast at any size.\n    api.colorAt(x, y, ink)  the color this layer's Color setting asks for (Ink, Photo, Tone or Duotone)\n    api.lines()             the user's lines, if your plugin sets usesLines: true\n                            [{ pts: [[x, y, halfWidth], ...], closed, text }]\n\n    Text helpers:\n    api.text()              an endless stream of the layer's text. Call .next() for one character.\n    api.words()             the text split into words or lines\n    api.measure(s, size, weight, font)  width of a string in pixels\n\n    Drawing:\n    api.addText(s, x, y, { size, angle, color, font, weight, align: 'center' | 'left', alpha })\n                            angle is in radians. x, y is the center of the letter (or its left side).\n    api.addRect(x, y, w, h, { color, alpha })\n    yield* api.writeAlong(paths, { size })   writes the layer's text along your own paths,\n                            the same way the Line text style does. paths: [[[x, y], [x, y], ...], ...]\n\n    Free of charge: removed background, Focus and fade, Effects, Limit to inks, color models\n    and every export (PNG, SVG, PDF, CMYK) work on plugin styles without extra code.\n\n    Controls (the settings panel). Types:\n      range   { key, label, type: 'range', min, max, step }\n      toggle  { key, label, type: 'toggle' }\n      choice  { key, label, type: 'choice', options: [[value, 'Label'], ...] }\n      text    { key, label, type: 'text' }      textarea { key, label, type: 'textarea' }\n      font    { type: 'font' }                  color    { type: 'color', options: ['ink', 'image', 'tone', 'duotone'] }\n      ink     { key, label, type: 'ink' }       (a single color picker)\n    Add more: true to tuck a control under \"More controls\".\n*/\n\nSungfluence.plugin({\n  api: 1,                         // the plugin API version this file was written for\n  id: 'my-scatter',               // unique: lowercase letters, digits and dashes\n  name: 'My scatter',             // shown on the style tile\n  icon: 'a*b',                    // up to 3 characters shown on the tile\n  version: '1.0.0',\n  author: 'Your name',\n  description: 'Scattered letters. Darker parts of the picture get more and bigger letters.',\n\n  // Starting values. text, font, weight, color, upper and sep are understood by SungFluence too.\n  defaults: { text: 'confetti', count: 9000, minSize: 5, maxSize: 26, spin: 0.7, power: 1.2, color: 'image', saturation: 1.3, font: 'sans', weight: 700, upper: false, sep: '' },\n\n  controls: [\n    { key: 'text', label: 'Letters to scatter', type: 'textarea' },\n    { key: 'count', label: 'How many tries', type: 'range', min: 1000, max: 30000, step: 500 },\n    { key: 'maxSize', label: 'Largest letter', type: 'range', min: 8, max: 90, step: 1 },\n    { key: 'minSize', label: 'Smallest letter', type: 'range', min: 2, max: 30, step: 1 },\n    { type: 'color', options: ['image', 'ink', 'tone', 'duotone'] },\n    { type: 'font' },\n    { key: 'spin', label: 'Spin', type: 'range', min: 0, max: 1, step: 0.05, more: true },\n    { key: 'power', label: 'Leave light areas emptier', type: 'range', min: 0.5, max: 3, step: 0.1, more: true },\n    { key: 'upper', label: 'Capitals', type: 'toggle', more: true }\n  ],\n\n  // render() runs every time a setting changes.\n  // Written as function* so it can yield progress (0 to 1). That keeps slow computers responsive.\n  *render(api) {\n    const p = api.params;\n    const letters = api.text({ sep: '' });                 // endless stream of the text\n    const tries = Math.round(p.count * (api.W * api.H) / (1600 * 1600)); // same density at any size\n\n    for (let i = 0; i < tries; i++) {\n      if (i % 600 === 0) yield i / tries;                  // progress for the progress bar\n\n      const x = api.random() * api.W;\n      const y = api.random() * api.H;\n      const ink = api.ink(x, y);                           // how dark the picture is here\n      if (api.random() > Math.pow(ink, p.power)) continue; // light areas keep fewer letters\n\n      let ch = letters.next();\n      if (ch === ' ') ch = letters.next();\n      if (ch === ' ') continue;\n\n      api.addText(ch, x, y, {\n        size: p.minSize + (p.maxSize - p.minSize) * ink,\n        angle: (api.random() - 0.5) * Math.PI * p.spin,    // radians\n        color: api.colorAt(x, y, ink)                      // follows the Color setting\n      });\n    }\n  }\n});\n"};
